#!/usr/bin/env bash
# Catch a PR branch that was cut from local `master` instead of `origin/master`.
#
# Generated by omp (DeepSeek V4.1 Flash) without human creative authorship.
# SPDX-License-Identifier: LGPL-2.1-or-later
#
# Local master carries docs/agents, tests and CI wiring that must not leak into
# upstream product PRs.  A branch based on it contains those local commits, so
# `merge-base HEAD master` stops being an ancestor of `origin/master`.
#
# The check is deliberately quiet on the integration branch and on ordinary
# local feature branches; set CHECK_PR_SCOPE=1 to force it for another branch.

set -u

ROOT=$(git rev-parse --show-toplevel 2>/dev/null) || {
    printf 'SKIP  PR scope (not inside a git checkout)\n'
    exit 0
}
cd "$ROOT"

branch=${GITHUB_HEAD_REF:-}
if [ -z "$branch" ]; then
    branch=$(git symbolic-ref --short -q HEAD 2>/dev/null || true)
fi

if [ -z "$branch" ] || [ "$branch" = master ] || [ "$branch" = main ]; then
    printf 'SKIP  PR scope (%s is an integration branch or detached HEAD)\n' \
        "${branch:-detached HEAD}"
    exit 0
fi

case "$branch" in
    pr/*) ;;
    *)
        if [ "${CHECK_PR_SCOPE:-0}" != 1 ]; then
            printf 'SKIP  PR scope (set CHECK_PR_SCOPE=1 to check %s)\n' "$branch"
            exit 0
        fi
        ;;
esac

if ! git rev-parse --verify --quiet master >/dev/null; then
    printf 'SKIP  PR scope (local master is absent)\n'
    exit 0
fi
if ! git rev-parse --verify --quiet origin/master >/dev/null; then
    printf 'SKIP  PR scope (origin/master is absent; fetch it first)\n'
    exit 0
fi

base=$(git merge-base HEAD master 2>/dev/null) || {
    printf 'FAIL  PR scope (HEAD and master have no merge base)\n'
    exit 1
}

if git merge-base --is-ancestor "$base" origin/master; then
    printf 'PASS  PR scope (base %s is on origin/master)\n' "$base"
    exit 0
fi

printf 'FAIL  PR scope: branch %s includes local master commits, not a clean origin/master base\n' "$branch"
printf 'base: %s\n' "$base"
printf 'local commits carried into the PR:\n'
git log --oneline "origin/master..$base" | head -20
printf 'files in the branch outside origin/master: '
git diff --name-only origin/master...HEAD | wc -l
printf 'Rebase the product commits: git rebase --onto origin/master %s\n' "$base"
exit 1
